  activeFolder: "",
  selectedNotes: new Set<string>(),
  lastSelectedNote: "",
  activeNote: null,
};

const resolveValue = <T,>(value: SetValue<T>, current: T): T =>
  typeof value === "function" ? (value as (current: T) => T)(current) : value;

