  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--ui-border);
  font-size: 12px;
}

.note-review-toolbar span,
.note-review-heading p,
.note-review-placeholder {
  color: var(--ui-muted);
}

.note-review-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 0 24px 40px;
  user-select: text;
}

.note-review-note {
  max-width: 760px;
  margin-inline: auto;
  padding-block: 28px;
}

.note-review-note + .note-review-note {
  border-top: 1px solid var(--ui-border);
}

.note-review-heading {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 16px;
}

.note-review-heading > div { min-width: 0; }
.note-review-heading button { flex-shrink: 0; }
.note-review-heading h2 { margin: 0; font-size: 13px; font-weight: 600; overflow-wrap: anywhere; }
.note-review-heading p { margin: 4px 0 0; font-size: 11px; overflow-wrap: anywhere; }
.note-review-placeholder { font-size: 13px; }
.note-review-error { padding: 12px 24px; color: var(--destructive); font-size: 13px; }

.note-review .tiptap-content,
.app.sidebar-collapsed .note-review .tiptap-content {
  min-height: 0;
  padding: 0;
  font-size: var(--editor-font-size, 14px);
}

.note-review .tiptap-content::after { display: none; }
EOF
