    });
  }
  if (removableFolders.length > 0) {
    selectionCommands.push({
      id: "delete-folders",
      label: `Delete ${removableFolders.length} folder${removableFolders.length > 1 ? "s" : ""}`,
      icon: Trash2Icon,
      keywords: ["remove"],
      run: () => void deleteFolders(removableFolders),
