  const frontmatterBody = splitFrontmatterBlock(frontmatterBlock);
  const lines = frontmatterBody ? frontmatterBody.split("\n") : [];
  const keyRe = new RegExp(`^\\s*${escapeRegExp(key)}\\s*:`);
