import React, {useState,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {AppearanceProvider} from './app/state/appearance-store';
import {SecurityProvider} from './features/security/hooks/security-context';
import {ProfilesProvider} from './features/profiles/hooks/profiles-context';
import {SelectionProvider,useSelection} from './app/state/selection-store';
import {EditorProvider,useEditor} from './features/notes/editor/hooks/editor-context';
import {NotesTreeProvider} from './features/notes/navigation/state/notes-tree-context';
import {NoteEditor} from './features/notes/editor/components/note-editor';
import {MultiNoteReview} from './features/lens/components/multi-note-review';
import {CommandPalette} from './features/command-palette/components/command-palette';
import {getActiveNoteEditor} from './features/notes/editor/lib/editor-bridge';
import './app/app.css';
const notePaths=['Feed/one.md','Feed/two.md'];
const notes=notePaths.map((path,i)=>({path,title:i?'Evening notes':'Morning notes',dateLabel:'Today',isRecording:false,transcriptionStatus:null}));
const source=Object.fromEntries(notePaths.map((path,i)=>[path,`---\nid: note-${i}\ncreated_ms: 1788800000000\n---\n# ${i?'Evening':'Morning'}\n\nA paragraph to keep.\n\n${i?'Second note selected text.':'Confidential paragraph.\n\nAnother selected paragraph.'}\n\nClosing thoughts.`]));
window.tagCheck={source,getActiveNoteEditor};
const noop=()=>{};
window.__TAURI_INTERNALS__={transformCallback:()=>1,unregisterCallback:noop,invoke:async(cmd,args)=>{
 if(cmd==='get_profiles')return {active_profile_id:'tag-check',profiles:[{id:'tag-check',name:'Tag check',description:'',notes_root:'/tmp/tag-check',settings:{}}],app_config:{note_file_name_format:'uuid_v7'}};
 if(cmd==='get_security_state')return {enabled:false,locked:false};
 if(cmd==='get_tree')return {name:'root',path:'',notes:[],children:[{name:'Feed',path:'Feed',children:[],notes:notePaths.map(path=>({path,name:path.split('/').pop()}))}]};
 if(cmd==='list_note_previews')return args.paths.map(path=>({path,content:source[path],meta:{created_ms:1788800000000,updated_ms:1788800000000}}));
 if(cmd==='read_note')return source[args.path];
 if(cmd==='write_note'){source[args.path]=args.content;return;}
 if(cmd==='plugin:event|listen')return 1;
 if(cmd==='plugin:event|unlisten')return;
 throw Error('Unexpected command '+cmd);
}};
function Check(){
 const [review,setReview]=useState(false);
 const selectNote=useSelection(s=>s.selectNote);
 const editor=useEditor();
 return <div style={{height:'100vh',maxWidth:840,margin:'auto',display:'flex',flexDirection:'column',background:'white'}}>
 <nav><button onClick={()=>{setReview(false);selectNote(notePaths[0],'Feed')}}>Open single</button> · <button onClick={()=>{setReview(true);selectNote(notePaths[0],'Feed',new Set(notePaths))}}>Open review</button></nav>
 <div className="editor-body">{review?<MultiNoteReview notes={notes} onBeforeRead={editor.flushSave}/>:<NoteEditor documentKey={editor.loadedNotePath} markdown={editor.noteContent} onChange={editor.handleEditorChange}/>}</div>
 <CommandPalette onOpenSettings={noop} onOpenFeed={noop} onOpenArchive={noop} onMoveFocusRestore={noop} onNewRecording={noop} onImportHandwriting={noop}/>
 </div>;
}
function Root(){const flush=useRef(null);return <AppearanceProvider><SecurityProvider><ProfilesProvider flushSaveRef={flush}><SelectionProvider><EditorProvider><NotesTreeProvider><Check/></NotesTreeProvider></EditorProvider></SelectionProvider></ProfilesProvider></SecurityProvider></AppearanceProvider>}
createRoot(document.getElementById('root')!).render(<Root/>);
EOF
